-- ============================================================
-- 007_hint_trivia.sql
-- Menambah kolom `hint` pada quiz_questions dan mengisinya untuk
-- seluruh 240 soal trivia (20 soal x 12 negara).
--
-- Petunjuk berupa satu kalimat yang mengarahkan tanpa menyebut
-- jawaban. Aman dijalankan ulang (idempoten).
-- ============================================================

alter table public.quiz_questions add column if not exists hint text;

update public.quiz_questions q
set hint = v.hint
from public.missions m,
(values
  -- MY
