where q.mission_id = m.id
  and m.type = 'trivia'
  and m.country_code = v.country_code
  and q.question = v.question;

-- Pengaman: batalkan seluruh migrasi bila ada soal yang belum terisi
-- (misalnya teks soal di database berbeda dari seed 002_misi.sql).
do $$
declare n int;
begin
  select count(*) into n from public.quiz_questions where hint is null or hint = '';
  if n > 0 then
    raise exception 'Masih ada % soal tanpa hint. Periksa kecocokan teks soal.', n;
  end if;
end $$;
